    "content": "有人来公司应聘销售经理，董事长助理曹总亲自对其进行了面试。 面试过程极为简单，让我也一时有些诧异。曹总一共就提了三个问题： 第一个问题：你有车吗？ 第二个问题：你有客户资源吗？ 第三个问题：你能喝酒吗？ 求职者回答道：“我自己有车，每天上下班开开；行业里的客户资源，这些年也积累了不少，不过就是酒量不行。” 曹总直接了当的说道：“酒量就是销量，没有酒量，是做不好销量的。”于是，就让面试者回家等通知了。 我有些不解的问曹总：“这样面试是不是太草率了？”他回答道：“我提的这三个问题都是有针对性的。有车才可以随时接送客户；…"
