    "author": "杨雨坤",
    "description": "爸爸深度参与育儿也是一种对自己大脑的保护。 “一孕傻三年”和产后抑郁 “一孕傻三年”这句话，我第一次听到的时候还笑。后来亲自带孩子，才明白应该是“谁带娃谁傻三年”。 我没经历怀孕，可那种有了小孩之后脑子慢半拍的状态我太熟悉了。每天晚上睡不够，白天还要想着研究的事。刚打开电脑想写东西，思路还没打开，就被自己打断。那种感觉像大脑在对自己降频，整个人都笨笨的。 这种脑子里仿佛糊住了的感觉，不是简单的“累了”可以解释的。照顾孩子的那几年，身体几…",
    "content": "爸爸深度参与育儿也是一种对自己大脑的保护。 “一孕傻三年”和产后抑郁 “一孕傻三年”这句话，我第一次听到的时候还笑。后来亲自带孩子，才明白应该是“谁带娃谁傻三年”。 我没经历怀孕，可那种有了小孩之后脑子慢半拍的状态我太熟悉了。每天晚上睡不够，白天还要想着研究的事。刚打开电脑想写东西，思路还没打开，就被自己打断。那种感觉像大脑在对自己降频，整个人都笨笨的。 这种脑子里仿佛糊住了的感觉，不是简单的“累了”可以解释的。照顾孩子的那几年，身体几乎没机会恢复。皮质醇一直维持高水平，神经系统长时间处于警觉模式。皮质醇本来能帮人…"
