    "content": "这是9月12日在沙特阿拉伯贾赞省图沃勒县拍摄的受损建筑和车辆。新华社发（沙特通讯社供图） 新华社利雅得9月12日电（记者罗晨 王海洲）沙特阿拉伯民防总局12日晚发表声明说，沙特贾赞省图沃勒县当天遭到也门胡塞武装的袭击，造成2人受伤、多栋建筑和一些车辆受损。 沙特民防总局强调，袭击民用目标公然违反国际人道法，有关方面已按照既定程序处理这一事件。 也门胡塞武装同日说，在过去48小时内，沙特战机对也门7个省份进行了129次空袭。该武装警告称这些空袭“不会得不到回应和惩罚”。 沙特阿拉伯民防总局12日晚发表声明说，沙特贾赞…"
