    "description": "新华社巴黎9月12日电（记者乔本孝）法国检方12日晚说，暂无证据证明前一日在法国北部城市鲁昂发生的列车脱轨事件是恐袭。 鲁昂检察官塞巴斯蒂安·加卢瓦12日晚说，初步调查显示，事发火车行驶的轨道上放置的一截铁轨是造成火车脱轨的直接原因，当前没有进一步证据指向恐袭。 加卢瓦说，事故导致的重伤者已脱离生命危险。 11日晚，一列载有180多人的火车在鲁昂附近脱轨，造成44人受伤，其中一人伤势严重。警方认为列车脱轨可能因有人蓄意破坏。 另据法国媒…",
    "content": "新华社巴黎9月12日电（记者乔本孝）法国检方12日晚说，暂无证据证明前一日在法国北部城市鲁昂发生的列车脱轨事件是恐袭。 鲁昂检察官塞巴斯蒂安·加卢瓦12日晚说，初步调查显示，事发火车行驶的轨道上放置的一截铁轨是造成火车脱轨的直接原因，当前没有进一步证据指向恐袭。 加卢瓦说，事故导致的重伤者已脱离生命危险。 11日晚，一列载有180多人的火车在鲁昂附近脱轨，造成44人受伤，其中一人伤势严重。警方认为列车脱轨可能因有人蓄意破坏。 另据法国媒体报道，在事件中受伤的火车司机证实，当时看到火车行驶前方轨道上放有异物。报道援引…"
