    "content": "12/09/2026 - 21:59 周六（9月12日）晚，席琳·迪翁在巴黎西郊重返舞台。距离她上一次举办演唱会已经过去6年多了。2022年，她被诊断出患有一种无法治愈的神经系统疾病，迫使她暂时放下自己的演艺事业。在今晚的舞台上，这位唱片销量超过2.6亿张的魁北克歌坛天后，以《On ne change pas》（“人不会改变”）这首歌作为开场，演唱时她一度因情绪过于激动而落泪，不得不暂时停唱。但她说：“这是喜悦的泪水。” 经过40年的演艺生涯，如今58岁的席琳·迪翁拥有数量庞大的流行歌曲作品，其中许多歌曲跨越世代。…"
