    "content": "新华社科威特城9月12日电（记者尹炣）萨那消息：也门胡塞武装12日表示，在过去48小时内，沙特战机对也门7个省份进行了129次空袭。 胡塞武装发言人叶海亚·萨雷亚当天在社交媒体平台发布声明称，沙特空军的F-15战斗机和“台风”战斗机空袭了也门西南部塔伊兹省、东北部马里卜省、红海沿海荷台达省以及北部焦夫省、萨达省、阿姆兰省和哈杰省。 他警告说，这些空袭“不会得不到回应和惩罚”。 近期，胡塞武装加大对政府军攻势，并宣布对支持也门政府的沙特阿拉伯实施海上禁运。也门政府军和胡塞武装10日分别证实，胡塞武装当天攻占红海战略要…"
