    "content": "12/09/2026 - 20:53 乌克兰官员周六（9月12日）表示，随着俄罗斯加强对乌克兰关键产业和基础设施的袭击，乌克兰经济2026年国内生产总值（GDP）可能因此减少1.5个百分点。乌方官员同时警告，今年冬季可能将“非常艰难”。 自2022年2月发动全面入侵以来，俄罗斯持续大规模打击乌克兰能源领域。今年夏季以来，俄方进一步加强导弹和喷气式无人机袭击，而乌克兰方面难以将其全部拦截。 粮食出口是乌克兰重要的收入来源，这些袭击不仅导致乌克兰通过黑海出口粮食受阻，还波及金属冶炼企业这一重要产业，以及铁路、大型仓储设…"
