    "content": "9月12日，在意大利威尼斯，《鸽环》导演张妤琦（右）、陶世欣在颁奖仪式上与奖杯合影。新华社记者 王楷焱 摄 新华社意大利威尼斯9月12日电（记者任耀庭 王楷焱）中国VR短片《鸽环》12日获得第83届威尼斯国际电影节“威尼斯沉浸单元”最高奖项——“威尼斯沉浸大奖”。 《鸽环》由张妤琦、陶世欣执导，以祖孙共同寻找遗失鸽环的经历为线索，讲述中国普通家庭中的记忆与亲情。短片以虚拟现实和沉浸式装置等方式呈现，全长35分钟。 本届电影节的“威尼斯沉浸单元”共展映来自26个国家和地区的68部作品，其中30部入围竞赛。 9月12日…"
