    "content": "新华社新德里9月12日电 金砖国家领导人第十八次会晤新德里宣言（摘要） 金砖国家领导人重申秉持互尊互谅、主权平等、团结民主、开放包容、深化合作、协商一致的金砖精神。在过去20年金砖合作基础上，进一步强化扩员后的金砖政治安全、经贸财金、人文交流“三轮驱动”合作。通过促进和平，构建更具代表性、更加公平的国际秩序，重振和改革多边体系，推动实现可持续发展和包容性增长，深化金砖战略伙伴关系，造福各国人民。 赞赏金砖伙伴国为金砖国家合作作出的宝贵贡献。坚信金砖国家通过增强与新兴市场和发展中国家的伙伴关系，将进一步加强团结，促进…"
