    "content": "“金砖国家要坚定站在历史正确一边，勇做时代先锋，引领国际秩序朝着更加公正合理的方向发展，携手推动构建人类命运共同体。” 当地时间9月12日下午，习近平主席在印度新德里出席金砖国家领导人第十八次会晤第一阶段会议并发表重要讲话，为金砖国家在新形势下携手前行指明方向。 此次会晤正值金砖国家合作20周年。20年来，金砖合作机制不断发展壮大，成长为当今世界最具影响力的新兴市场和发展中国家合作平台，展现出蓬勃生机活力。 “成为新兴市场和发展中国家联合自强的典范”“为世界提供稳定性和正能量”“迈入‘大金砖合作’高质量发展新阶段”…"
