    "content": "新华社多哈9月12日电（记者汪强）据卡塔尔半岛电视台12日报道，伊朗外交部发言人巴加埃表示，伊朗和阿曼预计将在14日举行的相关地区会议上，向海湾国家通报两国有关霍尔木兹海峡通航问题的磋商结果。 巴加埃在接受半岛电视台采访时说：“作为会议议程的一部分，我们将向与会代表团通报伊朗和阿曼就船只安全通过霍尔木兹海峡问题进行磋商的结果。” 巴加埃强调，地区安全应由地区国家自身保障，不应受到域外力量干预。“作为邻国，我们必须开展对话、建立互信，从而构建一个以地区所有国家的意愿和共同利益为基础的地区安全体系。” 伊朗与阿曼8月2…"
