    "content": "新华社北京9月12日电 题：从服贸会看服务设计如何赋能中国制造 新华社记者邹多为、戴锦镕、丁乐 当3000年前的青铜器“触手可及”，当毛绒玩具可以识别人类情绪并作出回应，当冰箱贴融合起黄绿色琉璃瓦与古典祥瑞纹样……9月12日，2026年中国国际服务贸易交易会迎来公众开放日，无处不在的巧思新意不仅吸引着众多观众驻足停留，更展现出服务设计赋能中国制造攀高向优的生动实践。 说起服务设计，不禁有人要问这究竟是什么？ 就在本届服贸会期间举行的全球（中国）服务设计大会上，同济大学设计创意学院院长辛向阳表示，服务设计不仅是优化前…"
