    "description": "新华社英国布伦特伍德9月12日电（记者马邦杰）斯诺克英格兰公开赛12日展开半决赛较量，中国名将丁俊晖以2:6不敌阿里·卡特，无缘决赛。 丁俊晖开局表现不错，首局打出单杆98分，之后又在第三局打出单杆65分，前三局战罢以2:1领先。 第四局，台面局势较为复杂，卡特抓住机会赢下这一局。此后，比赛几乎成了这位47岁英格兰选手的“独角戏”，他连下4局，以6:2锁定胜利。 决赛中，卡特将迎战马克·威廉姆斯与肖恩·墨菲之间的胜者。",
    "content": "新华社英国布伦特伍德9月12日电（记者马邦杰）斯诺克英格兰公开赛12日展开半决赛较量，中国名将丁俊晖以2:6不敌阿里·卡特，无缘决赛。 丁俊晖开局表现不错，首局打出单杆98分，之后又在第三局打出单杆65分，前三局战罢以2:1领先。 第四局，台面局势较为复杂，卡特抓住机会赢下这一局。此后，比赛几乎成了这位47岁英格兰选手的“独角戏”，他连下4局，以6:2锁定胜利。 决赛中，卡特将迎战马克·威廉姆斯与肖恩·墨菲之间的胜者。"
