    "content": "新华社日本名古屋9月12日电（记者岳晨星）在爱知·名古屋亚运会12日的男篮C组比赛中，中国队以105:59大胜巴林队，取得两连胜。 9月12日，中国队球员廖三宁（右）在比赛中拼抢。新华社记者 贾浩成 摄 中国队此役由廖三宁、庞峥麟、李弘权、胡金秋和朱俊龙首发，开场利用快速攻防转换打出9:0的得分高潮。廖三宁之后连得5分，将比分改写为18:6，迫使巴林队请求暂停。暂停后，他突破打成“2+1”，首节4投全中，连同罚球得到10分，帮助中国队以32:11领先。 第二节中国队进攻节奏有所放缓，巴林队则在进攻端屡屡得手，单节得…"
