    "description": "中新网拉萨9月12日电(记者 赵延)9月12日上午，西藏印社成立大会暨第一次会员代表大会在西藏美术馆学术报告厅举行。经西藏自治区民政厅、西藏自治区文联批准，西藏印社正式挂牌成立。当日，“印镌雪域——庆祝中国共产党成立105周年、西藏和平解放75周年暨西藏印社成立篆刻展”(以下简称：“印镌雪域”)同步开展。",
    "content": "中新网拉萨9月12日电(记者 赵延)9月12日上午，西藏印社成立大会暨第一次会员代表大会在西藏美术馆学术报告厅举行。经西藏自治区民政厅、西藏自治区文联批准，西藏印社正式挂牌成立。当日，“印镌雪域——庆祝中国共产党成立105周年、西藏和平解放75周年暨西藏印社成立篆刻展”(以下简称：“印镌雪域”)同步开展。"
