    "author": "黄国保,肖思思,王浩明",
    "description": "9月11日晚，开心麻花原创互动喜剧秀《新桃花源记》在横琴文化艺术中心开心麻花剧场迎来全国首演。该剧是横琴首个原创互动喜剧秀，由琴澳团队联合共创。剧目重构《桃花源记》经典故事，讲述桃源少女穿越时空，与横琴青年相遇的奇幻故事。剧场前厅打造沉浸式桃源场景，融合AI互动、舞台喜剧，观众可全程参与演出。 记者：肖思思、王浩明、黄国保 新华社音视频部制作",
