    "pub_date": "2026-09-12 20:42:39",
    "author": "",
    "description": "据气象部门预报，受南海热带低压影响，9月13日至15日，海南岛等地部分地区有大到暴雨、局地大暴雨，山洪和地质灾害、中小河流洪水以及城市内涝等灾害风险高。根据《国家防汛抗旱应急预案》及有关规定，国家防总于9月12日19时针对海南启动防汛四级应急响应。",
    "content": "据气象部门预报，受南海热带低压影响，9月13日至15日，海南岛等地部分地区有大到暴雨、局地大暴雨，山洪和地质灾害、中小河流洪水以及城市内涝等灾害风险高。根据《国家防汛抗旱应急预案》及有关规定，国家防总于9月12日19时针对海南启动防汛四级应急响应。"
