    "description": "做了个 Coding Agent 接入了我做的 Manim Workspace ( https://jizuobiao.xyz/workspace)。使用的是 DeepSeek V4 Flash 的模型，没想到在思考模式为 low 的情况下，就可以复刻很多数学动画了。对于一些数学题目，它甚至直接给求解了。 想学习 Manim 做数学动画，或者就做一些简单的数学动画的朋友可以体验一下。我测了一下，简单的图形，基本上就 1-2 角钱的样子就…",
    "content": "做了个 Coding Agent 接入了我做的 Manim Workspace ( https://jizuobiao.xyz/workspace)。使用的是 DeepSeek V4 Flash 的模型，没想到在思考模式为 low 的情况下，就可以复刻很多数学动画了。对于一些数学题目，它甚至直接给求解了。 想学习 Manim 做数学动画，或者就做一些简单的数学动画的朋友可以体验一下。我测了一下，简单的图形，基本上就 1-2 角钱的样子就可以完成。新用户赠送了 1000 积分，方便大家进行体验。 有什么建议，欢迎评价…"
