    "content": "新华社郑州9月12日电 题：中原乡村蹚出产业新通途 新华社记者王前慧 初秋，河南省禹州市磨街乡大涧村红薯地里藤蔓铺展，豫涧露营地帐篷错落，这个如今森林覆盖率超90%的村庄，曾是典型的煤炭资源村。在豫南，驻马店确山县竹沟镇竹沟村小王庄的提琴制作工厂里，工人们刻刀轻转，琴头渐显。 两个村庄，一个告别“乌金经济”，一个“无中生有”打造提琴产业。资源禀赋不同，却都完成了从传统产业向特色产业的跨越。 大涧村的变化，始于一场“断腕”式的抉择。村党委书记陈海昌介绍，过去村里依赖煤矿开采，生态欠账越来越多。站在提质转型的“十字路口…"
