    "pub_date": "2026-09-12 20:23:02",
    "author": "",
    "description": "中新网北京9月12日电 (记者 孙自法)中国科技馆9月12日向媒体通报说，2026年现代科技馆体系联合行动暨自然科学类博物馆系列科普活动——全国科普月推出的欢乐科学周，9月11日在甘肃科技馆启幕，通过线上线下相结合，联动全国130余家省、市、县级科技馆及各类行业机构同步开展科普惠民行动。",
    "content": "中新网北京9月12日电 (记者 孙自法)中国科技馆9月12日向媒体通报说，2026年现代科技馆体系联合行动暨自然科学类博物馆系列科普活动——全国科普月推出的欢乐科学周，9月11日在甘肃科技馆启幕，通过线上线下相结合，联动全国130余家省、市、县级科技馆及各类行业机构同步开展科普惠民行动。"
