    "title": "良渚博物院推出“琮谱”特展展现玉琮流传",
    "link": "http://www.news.cn/20260912/6c6015a58e09431d906622f1bbb12ff4/c.html",
    "pub_date": "2026-09-12 20:13:17",
    "author": "冯源",
    "description": "今年是良渚遗址发现90周年，以良渚遗址命名的良渚文化以玉器著名，而玉琮则是良渚玉器最具代表性的一种玉礼器。良渚博物院9月12日推出“琮谱——良渚遗址发现九十周年特展”，共展出来自海内外39家收藏机构的124件琮及琮式器。 图为展览现场。新华社记者冯源 摄 展览由浙江省文物局、杭州良渚遗址管理区管理委员会主办，良渚博物院、浙江省文物考古研究所承办，分为“起、合、承、转”四个叙事单元系统，梳理了玉琮历经5000余年，从诞生、鼎盛，到流转、重…",
    "content": "今年是良渚遗址发现90周年，以良渚遗址命名的良渚文化以玉器著名，而玉琮则是良渚玉器最具代表性的一种玉礼器。良渚博物院9月12日推出“琮谱——良渚遗址发现九十周年特展”，共展出来自海内外39家收藏机构的124件琮及琮式器。 图为展览现场。新华社记者冯源 摄 展览由浙江省文物局、杭州良渚遗址管理区管理委员会主办，良渚博物院、浙江省文物考古研究所承办，分为“起、合、承、转”四个叙事单元系统，梳理了玉琮历经5000余年，从诞生、鼎盛，到流转、重构的传承脉络。展品中既有良渚文化的玉琮，也有龙山文化、商代、西周、春秋战国以至明…"
